    assert client.get("/mode").json() == {"mode": "uji"}


def test_perubahan_environment_dibatalkan_otomatis():
    # monkeypatch dari pengujian sebelumnya sudah dibatalkan
    assert client.get("/mode").json() == {"mode": "produksi"}
