main.py<pre><code>import os
import time

from fastapi import FastAPI

app = FastAPI()


@app.get("/info")
def info():
    """Menunjukkan proses mana yang melayani request ini."""
    return {"pid": os.getpid()}


kunjungan = 0  # penghitung di memori: SETIAP proses punya salinannya sendiri


@app.post("/kunjungan")
def catat_kunjungan():
    global kunjungan
    kunjungan += 1
    return {"pid": os.getpid(), "kunjungan": kunjungan}


@app.get("/hitung")
def hitung(n: int = 20_000_000):
    """Pekerjaan yang benar-benar memakai CPU dengan jumlah langkah tetap (bukan menunggu).

    Mensimulasikan komputasi berat. Lama eksekusi bergantung pada kecepatan mesin.
    """
    mulai = time.perf_counter()
    total = 0
    for i in range(n):
        total += i * i
    return {"pid": os.getpid(), "detik": round(time.perf_counter() - mulai, 2)}
</code></pre> <ul> <li><code>GET /info</code> mengembalikan nomor proses (PID) yang melayani request.</li> <li><code>GET /hitung</code> menjalankan pekerjaan yang benar-benar memakai CPU dengan jumlah langkah tetap (<code>n</code> pengulangan). Ini mewakili komputasi berat.</li> <li><code>POST /kunjungan</code> menaikkan penghitung di memori dan mengembalikan nilainya bersama PID.</li> </ul>

config.py<pre><code>from functools import lru_cache
from typing import Literal

from pydantic import Field, SecretStr, model_validator
from pydantic_settings import BaseSettings, SettingsConfigDict

KUNCI_CONTOH = "ganti-dengan-kunci-acak"  # awalan pada berkas contoh; tidak boleh dipakai di produksi


class Settings(BaseSettings):
    # Urutan sumber (yang awal menang): argumen, variabel environment, berkas .env, berkas rahasia, nilai bawaan.
    # Dua berkas .env: yang belakang menimpa yang depan.
    # extra="ignore": entri di .env yang tidak cocok dengan field diabaikan (bawaan pydantic-settings:
    # "forbid", yang membuat aplikasi gagal mulai bila .env berisi entri lain, mis. milik Docker Compose).
    model_config = SettingsConfigDict(
        env_prefix="TUGASKU_", env_file=(".env", ".env.lokal"), extra="ignore"
    )

    lingkungan: Literal["pengembangan", "uji", "produksi"] = "pengembangan"
    mode_debug: bool = False
    database_url: str = "sqlite:///database.db"
    origin_diizinkan: list[str] = ["http://localhost:3000"]
    secret_key: SecretStr = Field(min_length=32)

    @model_validator(mode="after")
    def periksa_aturan_produksi(self):
        """Di produksi, tolak konfigurasi yang berbahaya. Aplikasi gagal mulai alih-alih berjalan dengan tidak aman."""
        if self.lingkungan == "produksi":
            masalah = []
            if self.mode_debug:
                masalah.append("mode_debug harus False")
            if "*" in self.origin_diizinkan:
                masalah.append("origin_diizinkan tidak boleh berisi '*'")
            if self.secret_key.get_secret_value().startswith(KUNCI_CONTOH):
                masalah.append("secret_key masih kunci contoh")
            if masalah:
                raise ValueError("Konfigurasi produksi tidak aman: " + "; ".join(masalah))
        return self


@lru_cache
def get_settings() -&gt; Settings:
    return Settings()
